def get_movie_info(movie_id):
    """Get movie info by ID"""
    if movie_id in MOVIE_DATABASE:
        return MOVIE_DATABASE[movie_id]
    return {"title": f"Movie {movie_id}", "poster": "https://via.placeholder.com/200x300?text=No+Poster", "year": "N/A"}
